      \end{block}
    \end{column}
    \begin{column}{0.48\textwidth}
      \begin{block}{Eje 3 o evidencia}
        \textit{Caso, cuadro comparativo, mapa, esquema, tabla o ejemplo aplicado.}
      \end{block}
      \begin{block}{Criterio de seleccion}
